/*
 * A278767  Expansion of Product_{k>=1} 1/(1 - x^k)^(k*(2*k-1)).
 * https://oeis.org/A278767
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) generated by ∏_{k≥1} 1/(1 - x^k)^{k(2k-1)} (Euler transform
 *            of the hexagonal numbers). The sequence satisfies the recurrence
 *            e(0)=1, e(n) = (1/n) * Σ_{k=1}^{n} B(k) * e(n-k), where
 *            B(k)=Σ_{d|k} d^2(2d-1). This implementation computes the
 *            recurrence using memoised arrays
 * Range:     u8 n <= 3, u16 n <= 8, u32 n <= 19, u64 n <= 32, u128 n <= 32,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

seq_t a(idx_t n) {
    /* static storage for values up to the largest n seen so far */
    static seq_t *B = NULL;          /* divisor‑sum array */
    static seq_t *E = NULL;          /* sequence values */
    static idx_t max_n = 0;          /* next free index (size of arrays) */

    if (n >= max_n) {
        idx_t new_size = n + 1;      /* need indices 0..n */
        B = (seq_t*)realloc(B, new_size * sizeof(seq_t));
        E = (seq_t*)realloc(E, new_size * sizeof(seq_t));
        /* initialise new entries to 0 */
        for (idx_t i = 1; i <= n; ++i)
            B[i] = 0;

        /* recompute B[1..n] from scratch */
        for (idx_t d = 1; d <= n; ++d) {
            seq_t val = (seq_t)d * d * ((seq_t)2*d - 1);  /* d^2*(2d-1) */
            for (idx_t k = d; k <= n; k += d)
                B[k] += val;
        }

        /* ensure e(0)=1, initialise if first call */
        if (max_n == 0) {
            E[0] = 1;
        }

        /* compute e(m) for all new indices */
        idx_t start = (max_n == 0) ? 1 : max_n;
        for (idx_t m = start; m <= n; ++m) {
            seq_t sum = 0;
            for (idx_t k = 1; k <= m; ++k)
                sum += B[k] * E[m - k];
            E[m] = sum / m;  /* exact division */
        }
        max_n = n + 1;   /* array size updated */
    }
    return E[n];
}
